p.codeblock:
p:-oxy-selected {
    -oxy-floating-toolbar: 
        oxy_label(text, "Platform: ")
        oxy_combobox(
            edit, '@platform', 
            editable, false, 
            values, 'windows, mac, linux', 
            labels, 'Windows, MacOS, Linux'
            )
}

@media oxygen and (platform:webapp) {
      *[class ~= "topic/table"],
      *[class ~= "topic/tgroup"] {
          -oxy-block-floating-toolbar:
              oxy_button(actionID, 'insert.table.row.above')
              oxy_button(actionID, 'insert.table.row.below')
              oxy_button(actionID, 'delete.table.row')
              '|'
              oxy_button(actionID, 'insert.table.column.before')
              oxy_button(actionID, 'insert.table.column.after')
              oxy_button(actionID, 'delete.table.column')
              '|'
              oxy_button(actionID, 'show.table.properties')
              oxy_button(actionID, 'sort_table')
              '|'
              oxy_button(actionID, 'table.join')
              oxy_button(actionID, 'table.split');
      }
  }
